FIX = {
    3: (u'\u5be6\u7121\u6240\u77e5\u800c\u81ea\u7a31\u4e0a\u4eba\u6cd5\uff0c\u8207\u589e\u4e0a\u6162\u4e4b\u81ea\u8aa4\uff0c\u754c\u5728\u4f55\u8655\uff1f'
        u'\u70ba\u53e3\u8179\u800c\u8a50\u5931\u4fe1\u606f\uff0c\u7f6a\u70ba\u4f55\u53cd\u91cd\u65bc\u81ea\u8a87\uff1f',
        u'**\u3010\u7b2c\u56db\u6ce2\u7f85\u5937\uff08\u5927\u5984\u8a9e\uff0c\u6975\u5211\u65e2\u8d77\u3011**<br>'
        u'\u69cb\u6210\u5728\u300e\u7121\u8b49\u800c\u7a31\u5f97\u300f\u51bc\u5927\u773e\u4e2d\u6545\u8a50\uff1b\u589e\u4e0a\u6162\uff08\u81ea\u8b42\u5df2\u8b49\uff09\u81ea\u59cb\u4e0d\u5165\u3002'
        u'\u5f8b\u7a31\u6b64\u70ba\u300e\u6700\u4e0a\u5927\u8d3f\u300f\u2014\u2014\u6240\u7be1\u8005\u4e0d\u662f\u4e00\u98ef\uff0c\u800c\u662f\u4eba\u4e88\u5176\u4f9b\u990a\u4e4b\u4fe1\u5fc3\uff0c'
        u'\u6545\u4e0d\u5f97\u4ee5\u6240\u8c42\u8005\u5fae\u800c\u964d\u968e\uff1b\u6ec5\u64ef\u4e0d\u5171\u4f4f\u3002'),
    17: (u'\u9053\u8207\u975e\u9053\u4e4b\u5224\uff0c\u7e6b\u65bc\u8eab\u8655\u4f55\u8655\uff0c\u6216\u7e6b\u65bc\u300e\u60f3\u300f\uff1f'
        u'\u5f70\u6b32\u4ed6\u8eab\u8207\u81ea\u6b32\u5df1\u8eab\uff0c\u7f6a\u8cac\u662f\u5426\u540c\u50f9\uff1f',
        u'**\u3010\u50e7\u6b98\u2194\u5077\u862d\u906e\uff08\u5883\u60f3\u5b9a\u968e\uff09\u3011**<br>'
        u'\u975e\u9053\u800c\u4f5c\u9053\u60f3\u3001\u9053\u800c\u4f5c\u975e\u9053\u60f3\uff0c\u5404\u4f9d\u5176\u60f3\u7d50\u7f6a\uff1a\u6b32\u60f3\u5728\u975e\u9053\u5247\u50e7\u6b98\uff0c'
        u'\u751f\u7591\u800c\u884c\u5247\u4e0b\u54c1\u5077\u862d\u906e\u3002\u5883\u60f3\u8aa4\u8a8d\u53ea\u964d\u5176\u968e\uff0c\u4e0d\u8f49\u5176\u6027\u3002'),
    35: (u'\u53d7\u66b4\u8005\u65bc\u4e8b\u5f8c\u751f\u8d77\u4e4b\u8eab\u76f8\uff0c\u662f\u72af\u7de3\u9084\u662f\u75c5\u76f8\uff1f'
        u'\u5236\u5ea6\u7576\u8cac\u5176\u5b88\u7bc0\uff0c\u9084\u662f\u8b77\u5176\u5fa9\u539f\uff1f',
        u'**\u3010\u7121\u72af\uff08\u81ea\u7531\u610f\u5fd7\u5df2\u5931\uff09\u3011**<br>'
        u'\u696d\u9053\u93c8\u5728\u524d\u7aef\u6298\u65b7\uff0c\u70ba\u6a02\u3001\u70ba\u8a31\u7686\u4e0d\u53ef\u5f92\u9580\uff0c\u6212\u9ad4\u7121\u640d\uff1b'
        u'\u5176\u5f8c\u4e4b\u51fa\u96e2\u8207\u89ba\u9192\u662f\u884c\u9053\u4e4b\u59cb\uff0c\u975e\u8655\u5206\u4e4b\u7531\u3002\u5f8b\u7d55\u4e0d\u4ee5\u8eab\u76f8\u8ffd\u8cec\u53d7\u5bb3\u8005\u3002'),
    71: (u'\u540c\u662f\u538c\u8eab\uff0c\u4e00\u4fee\u4e00\u6b7b\uff1b\u6cd5\u9580\u4e4b\u5931\u8207\u6bba\u696d\u4e4b\u754c\uff0c\u5982\u4f55\u5207\u958b\uff1f'
        u'\u52f8\u9000\u8207\u958b\u63db\uff0c\u8ab0\u70ba\u5176\u8cec\uff1f',
        u'**\u3010\u958b\u63db\u7121\u72af\uff0c\u52f8\u6b7b\u5165\u6975\u3011**<br>'
        u'\u4e0d\u51c0\u89c0\u81f4\u9b31\uff0c\u4f5b\u4e0d\u5750\u5176\u6cd5\u9580\u4e4b\u5931\uff0c\u800c\u5225\u6559\u6578\u606f\u2014\u2014\u5e2b\u4e4b\u8cec\u5728\u5f9e\u6642\u8abf\u6574\uff1b'
        u'\u82e5\u8b79\u7fa9\u6b7b\u3001\u5feb\u52f8\u6b7b\u5247\u7b2c\u4e09\u6ce2\u7f85\u5937\u3002\u6cd5\u9580\u8d70\u504f\u975e\u7f6a\uff0c\u63a8\u4eba\u8d74\u6b7b\u662f\u7f6a\u3002'),
    73: (u'\u5ff5\u982d\u66fe\u6307\u4ed6\u4eba\u4e4b\u7269\uff0c\u8eab\u53e3\u672a\u767c\uff0c\u662f\u5426\u5df2\u6210\u76dc\u696d\uff1f'
        u'\u300e\u4f5c\u662f\u5ff5\u300f\u8207\u300e\u9063\u4eba\u53d6\u300f\u4e4b\u754c\u5728\u54ea\u4e00\u524e\uff1f',
        u'**\u3010\u610f\u5730\u7121\u72af\uff0c\u4e0d\u61c9\u4f5c\u3011**<br>'
        u'\u7121\u8868\u696d\u5247\u4e0d\u5165\u516c\u5802\uff1b\u4f5b\u8a3b\u300e\u7121\u72af\uff0c\u4e0d\u61c9\u4f5c\u5982\u662f\u4e8b\u300f\uff0c'
        u'\u5165\u6559\u8beb\u9632\u8b77\uff08\u7b2c\u4e09\u503c\uff09\u800c\u4e0d\u5165\u8655\u5206\u968e\u68af\u3002\u76dc\u5fc3\u8d77\u800c\u672a\u52d5\uff0c\u662f\u5fc3\u75c5\u975e\u7f6a\u76f8\u3002'),
    60: (u'\u6240\u85cf\u8005\u503c\u4e0d\u904e\u4e94\u9322\uff0c\u6240\u50b7\u8005\u662f\u4ed6\u4e4b\u5b89\u5b9a\uff1b'
        u'\u4ee5\u6232\u7b11\u70ba\u63a9\u4e4b\u4fb5\u72af\uff0c\u7f6a\u5f9e\u7269\u8a08\u9084\u662f\u5f9e\u5fc3\u8a08\uff1f',
        u'**\u3010\u6ce2\u9038\u63d0\uff08\u4e0d\u8a08\u7269\u503c\uff09\u3011**<br>'
        u'\u72af\u7de3\u5728\u300e\u4ee4\u4ed6\u6467\u607c\u300f\u4e4b\u6545\u610f\uff0c\u4e0d\u5728\u8ca1\u984d\uff0c\u6545\u4e0d\u5f85\u6eff\u4e94\u9322\uff1b'
        u'\u82e5\u517c\u61f7\u76dc\u5fc3\u4e26\u8209\u96e2\u672c\u8655\uff0c\u5247\u5225\u5165\u76dc\u6212\u5171\u53e5\u800c\u5169\u7f6a\u5404\u5b58\u3002\u4e00\u6642\u6232\u7b11\uff0c\u5169\u689d\u754c\u6a19\u3002'),
    68: (u'\u7591\u800c\u672a\u98df\uff0c\u662f\u6146\u606f\u9084\u662f\u653e\u9038\uff1f\u5be9\u614e\u904e\u7576\u81f4\u6cd5\u9580\u7a92\u585e\uff0c\u5f8b\u5411\u54ea\u908a\u7684\u5e73\uff1f',
        u'**\u3010\u7121\u72af\uff08\u6cd5\u61c9\u723e\uff09\u3011**<br>'
        u'\u4e0d\u77e5\u800c\u7591\u8005\u7121\u72af\u2014\u2014\u7591\u5fc3\u4e0d\u6210\u5c08\u696d\u4e4b\u52dd\u89e3\uff0c\u696d\u9053\u672a\u5713\uff1b'
        u'\u4f5b\u53cd\u554a\u300e\u6cd5\u61c9\u723e\u300f\uff0c\u807d\u98f2\u3002\u6240\u7f6e\u4e4b\u6a19\uff1a\u4ee5\u6146\u606f\u70ba\u9ad4\u4e4b\u7591\u8207\u4ee5\u653e\u9038\u70ba\u9ad4\u4e4b\u7591\uff0c\u4e0d\u5f97\u540c\u79d1\u3002'),
    70: (u'\u82e6\u884c\u800c\u81ea\u6b98\uff0c\u662f\u6301\u6212\u9084\u662f\u72af\u6212\uff1f\u98df\u8089\u4e4b\u7981\u8207\u300e\u4e0d\u554f\u4f86\u6e90\u300f\u4e4b\u5931\uff0c\u540c\u79d1\u5426\uff1f',
        u'**\u3010\u5077\u862d\u906e\uff0b\u7a81\u5409\u7f85\uff08\u5169\u5c64\uff09\u3011**<br>'
        u'\u5272\u8eab\u8089\u4ee5\u975e\u56e0\u8a08\u56e0\uff0c\u975e\u89e3\u812b\u9053\uff0c\u4f5b\u5236\u4e0d\u5f97\u98df\u4eba\u8089\u2014\u2014\u81ea\u6b98\u4e4b\u5ff5\u963b\u65bc\u6559\u8beb\uff1b'
        u'\u96a8\u4f34\u4e0d\u554f\u4f86\u6e90\u5247\u5225\u7d50\u60e1\u4f5c\u3002\u52d5\u6a5f\u4e4b\u8b5a\u8aa0\u4e0d\u8d66\u77e5\u898b\u4e4b\u5012\u3002'),
    72: (u'\u7981\u98df\u5341\u7a2e\u8089\uff0c\u662f\u8b77\u751f\u9084\u662f\u907f\u8b60\uff1f\u70ba\u907f\u52de\u800c\u6b0a\u98df\uff0c\u8207\u70ba\u53e3\u8179\u800c\u5047\u6258\uff0c\u754c\u5982\u4f55\u5b9a\uff1f',
        u'**\u3010\u958b\u906e\u4ee5\u6cd5\u76ca\u5b9a\uff0c\u4e0d\u4ee5\u53e3\u5473\u5b9a\u3011**<br>'
        u'\u8c61\u99ac\u734b\u86c7\u4e4b\u7981\uff0c\u5728\u738b\u96e3\u3001\u8b60\u5acc\u8207\u751f\u9748\u4e4b\u8b77\uff1b\u6709\u8cca\u96e3\u800c\u98df\u8089\u5f97\u6d3b\uff0c\u5f8b\u958b\u5176\u7de3\u800c\u56b4\u5176\u60c5\u3002'
        u'\u81e8\u4e8b\u5148\u554f\u300e\u70ba\u547d\u5426\u300f\uff0c\u6b21\u554f\u300e\u70ba\u5473\u5426\u300f\u3002'),
    96: (u'\u7cbe\u9032\u4e4b\u91cf\u4ee5\u4f55\u70ba\u6e96\uff1f\u7de9\u6025\u7686\u5931\uff0c\u8ab0\u70ba\u9053\u5834\u5b9a\u4e2d\u7dda\uff1f',
        u'**\u3010\u7121\u72af\uff08\u5c0d\u6cbb\u4e4b\u55bb\uff09\u3011**<br>'
        u'\u4f5b\u4ee5\u7434\u5f26\u8f09\u6cd5\uff1a\u6025\u5247\u7e2e\u8072\uff0c\u7de9\u5247\u7d55\u8072\uff0c\u96e2\u6b64\u4e8c\u908a\u6545\u5f97\u95be\u3002'
        u'\u6389\u823e\u8207\u61f0\u61f2\u540c\u4e00\u75c5\u3001\u540c\u4e00\u85e5\uff1b\u6b64\u5247\u5165\u6559\u8beb\u9632\u8b77\uff0c\u4e0d\u5165\u5211\u540d\u3002'),
    99: (u'\u8863\u975e\u5df1\u6709\uff0c\u6682\u501f\u8207\u76dc\u53d6\u4f55\u522b\uff1f\u6025\u96e3\u4e4b\u958b\u8a31\uff0c\u662f\u5426\u9808\u5f85\u50e7\u5718\u7ff1\u78e8\u5148\u8a38\uff1f',
        u'**\u3010\u958b\u8a31\uff08\u6025\u96e3\u5148\u884c\uff0c\u50e7\u4e8b\u5f8c\u88dc\uff09\u3011**<br>'
        u'\u9732\u5f62\u4f86\u6295\uff0c\u807d\u501f\u8863\u52ff\u4ee4\u9732\u5f62\uff0c\u96a8\u6240\u53d6\u4ee4\u5f7c\u6b61\u559c\uff1b\u7136\u300e\u4e0d\u8207\u53d6\u5fc3\u300f\u4e4b\u754c\u4ecd\u5728\uff0c'
        u'\u4e8b\u5df4\u8655\u5206\u5176\u6240\u5c6c\u3002\u958b\u8a31\u6551\u5f62\uff0c\u4e0d\u5ee2\u7269\u6b0a\u3002'),
    40: (u'\u5e7c\u8005\u591c\u5bbf\u7121\u8655\uff0c\u8207\u672a\u53d7\u5927\u6212\u4eba\u5171\u5bbf\u4e4b\u7981\u76f8\u89f8\uff0c\u5b70\u5148\uff1f'
        u'\u8b77\u5e7c\u662f\u5426\u9808\u4ee5\u7834\u6212\u70ba\u50f9\u5131\uff1f',
        u'**\u3010\u958b\u7de3\uff08\u81f3\u4e09\u5bbf\u5373\u96e2\uff09\u3011**<br>'
        u'\u904e\u4e8c\u5bbf\u81f3\u4e09\u5bbf\u70ba\u8655\u6240\u2014\u2014\u5f8b\u7559\u4e00\u65e5\u4e4b\u7de9\uff0c\u975e\u8a31\u9577\u4f4f\uff1b'
        u'\u5982\u4f86\u81ea\u79fb\u5c31\u5f62\uff0c\u662f\u4e0a\u5ea7\u4e4b\u8b93\u4f4d\uff0c\u975e\u6212\u9ad4\u4e4b\u8b93\u4f4d\u3002\u958b\u906e\u4e4b\u5224\u5728\u300e\u6709\u671f\u300f\u3002'),
    59: (u'\u5165\u6751\u662f\u4e3a\u8b02\u98df\uff0c\u9084\u662f\u70ba\u89c0\u535a\uff1f\u300e\u975e\u6642\u300f\u8207\u300e\u4e0d\u5622\u300f\u4e8c\u7bc0\uff0c\u4f55\u8005\u70ba\u72af\u7de3\u4e4b\u6b63\uff1f',
        u'**\u3010\u6ce2\u9038\u63d0\uff08\u96d9\u8981\u4ef6\uff09\u3011**<br>'
        u'\u72af\u7de3\u5728\u975e\u6642\uff0b\u4e0d\u5622\u540c\u4f5c\uff1b\u6642\u81f3\u4e14\u5df2\u5622\u5247\u7121\u72af\u3002'
        u'\u535a\u6232\u4e4b\u60e1\u5728\u5931\u5a01\u5100\u8207\u751f\u8b60\u5acc\uff0c\u6545\u5f8b\u4e0d\u5f85\u8cc3\u8cc7\u591a\u5be1\u5373\u7d50\u58ca\u7f6a\u3002'),
    61: (u'\u778b\u604a\u4e00\u638c\uff0c\u5211\u5ea6\u5e7e\u4f55\uff1f\u8eab\u696d\u4e4b\u8f15\u91cd\uff0c\u4f9d\u50b7\u8de1\u9084\u662f\u4f9d\u5fc3\uff1f',
        u'**\u3010\u6ce2\u9038\u63d0\uff08\u7b2c\u4e03\u5341\u516b\u3001\u4e03\u5341\u4e5d\uff0c\u5169\u6212\u5404\u5225\uff09\u3011**<br>'
        u'\u778b\u604a\u6545\u4e0d\u6253\u800c\u627f\u8a9e\u3001\u4ee5\u624b\u62ce\u4eba\uff0c\u5404\u7d50\u4e00\u582f\uff1b\u7121\u50b7\u4ea6\u72af\uff0c'
        u'\u56e0\u5176\u6240\u58de\u8005\u662f\u50e7\u548c\u5408\u4e4b\u5834\u57df\uff0c\u975e\u8089\u4e4b\u7dea\u75db\u3002\u8eab\u53e3\u4e8c\u696d\u4e0d\u8a31\u6298\u640a\u3002'),
    62: (u'\u65c1\u807d\u4ed6\u4eba\u4e4b\u8b6c\uff0c\u672c\u8eab\u662f\u5426\u6210\u696d\uff1f\u5f48\u6307\u8b26\u6b4b\u8207\u50b3\u8a9e\u5411\u5f7c\uff0c\u7f6a\u5dee\u4f55\u8655\uff1f',
        u'**\u3010\u6ce2\u9038\u63d0\uff08\u59a8\u6ec5\u8b6c\uff09\u3011**<br>'
        u'\u72af\u7de3\u5728\u6b32\u805e\u5176\u8aaa\u4e4b\u7acb\u610f\u7ac4\u807d\uff0c\u4e0d\u5728\u4e8b\u5f8c\u4e4b\u8a55\u8ad6\uff1b\u82e5\u8b20\u6b6b\u5f48\u6307\u4ee5\u52d5\u5176\u8b6c\u610f\uff0c\u5225\u7d50\u60e1\u4f5c\uff1b'
        u'\u50b3\u8a9e\u5411\u5f7c\u5247\u5165\u5169\u820c\u3002\u6ec5\u8b6c\u4e4b\u5834\u9808\u6709\u9589\u53e3\u4e4b\u81ea\u7531\uff0c\u6545\u5f8b\u61f2\u7ac4\u807d\u4e0d\u61f2\u5728\u5834\u3002'),
    64: (u'\u8457\u8863\u4e4b\u76f8\u5982\u4f55\u6210\u72af\uff1f\u50e7\u670d\u662f\u5a01\u5100\u9084\u662f\u88dd\u98fe\uff0c\u5176\u5224\u6e96\u8209\u8ab0\uff1f',
        u'**\u3010\u7a81\u5409\u7f85\uff08\u5236\u6559\u4e4b\u8f15\u7f6a\uff09\u3011**<br>'
        u'\u773e\u5b78\u6cd5\u4ee5\u300e\u7576\u9f4a\u6574\u8457\u300f\u70ba\u6559\u4ee4\uff0c\u9055\u5247\u60e1\u4f5c\uff1b\u7f6a\u5728\u7981\u9006\u5236\u610f\uff0c\u4e0d\u5f85\u751f\u8b60\u5acc\u3002'
        u'\u6b64\u7d1a\u4e4b\u8a2d\uff0c\u4f7f\u7d30\u884c\u4e0d\u9808\u53e6\u7acb\u91cd\u5211\u3002'),
    65: (u'\u5165\u767d\u8863\u820d\u4e4b\u8eab\u76f8\uff08\u53c9\u8170\u3001\u8df3\u884c\u3001\u6389\u81c2\uff09\u70ba\u4f55\u9808\u5225\u7acb\u5b78\u8655\uff1f\u4e09\u76f8\u4e26\u5217\uff0c\u72af\u4e00\u5373\u6210\u7acb\u5426\uff1f',
        u'**\u3010\u7a81\u5409\u7f85\uff08\u96a8\u4e8b\u5404\u7d50\uff09\u3011**<br>'
        u'\u4e09\u76f8\u5404\u70ba\u4e00\u4e8b\uff0c\u96a8\u6d89\u4e00\u4e00\u7d50\u7f6a\u4e0d\u4e26\u6e1b\uff1b\u6240\u8b77\u8005\u662f\u767d\u8863\u4e4b\u4fe1\u5fc3\uff0c\u6545\u5224\u6e96\u5916\u7f6e\u65bc\u4ed6\u8005\u4e4b\u773c\u3002'
        u'\u6b64\u5373\u6b63\u7406\u4e8c\u4e4b\u5fae\u89c0\u5316\u3002'),
    66: (u'\u53bb\u89c0\u4f8e\u6a02\u8207\u88ab\u4f8e\u6a02\u4e4b\u4eba\u89c0\uff0c\u4f55\u8005\u70ba\u5f8b\u4e4b\u6240\u7981\uff1f\u300e\u770b\u300f\u4e4b\u696d\u6210\u65bc\u773c\uff0c\u9084\u662f\u6210\u65bc\u5f80\uff1f',
        u'**\u3010\u7a81\u5409\u7f85\uff08\u9632\u9038\u4e0d\u9632\u5a31\uff09\u3011**<br>'
        u'\u6240\u7981\u5728\u6563\u532f\u4e4b\u5f80\u89c0\uff0c\u4e0d\u5728\u8072\u8272\u4e4b\u672c\u8eab\uff1b\u75c5\u50cf\u5728\u8033\u76ee\u5916\u99b3\uff0c\u6545\u7d50\u8cac\u65bc\u300e\u5f80\u300f\u3002'
        u'\u4ee5\u5a01\u5100\u6cd5\u5835\u653e\u9038\u4e4b\u5f91\uff0c\u6b64\u70ba\u7b2c\u4e09\u503c\u4e4b\u5178\u578b\u3002'),
    67: (u'\u70ba\u8b77\u7269\u800c\u5bbf\u5854\uff0c\u8207\u70ba\u5b89\u9038\u800c\u5bbf\u5854\uff0c\u540c\u4e00\u8eab\u8655\u4f55\u4ee5\u7570\u5224\uff1f\u958b\u8a31\u4e4b\u754c\u5982\u4f55\u7559\u75d5\uff1f',
        u'**\u3010\u958b\u8a31\u4e8c\u7acb\uff08\u70ba\u5b88\u8b77\u3001\u70ba\u5805\u7262\uff09\u3011**<br>'
        u'\u6b62\u5bbf\u4e4b\u7981\u70ba\u96e2\u4fd7\u8b60\u5acc\uff1b\u82e5\u70ba\u5854\u7269\u4e4b\u5b88\u8b77\u3001\u7d93\u5df7\u4e4b\u5805\u7262\uff0c\u5247\u958b\u3002'
        u'\u5224\u6e96\u5728\u300e\u6240\u70ba\u4f55\u70ba\u300f\uff0c\u540c\u4e00\u5e8a\u8912\u800c\u5169\u5fc3\u5169\u6cd5\u3002'),
    69: (u'\u672a\u770b\u9580\u76f8\u800c\u8aa4\u5165\uff0c\u662f\u5931\u5ff5\u9084\u662f\u72af\u7de3\uff1f\u907f\u8b60\u4e4b\u8cec\uff0c\u6b78\u884c\u8005\u9084\u662f\u6b78\u5236\u6cd5\u4e4b\u50e7\u5718\uff1f',
        u'**\u3010\u7121\u8a18\u7121\u72af\uff0c\u7acb\u770b\u9580\u76f8\u4e4b\u5236\u3011**<br>'
        u'\u7121\u67d3\u5fc3\u3001\u7121\u6545\u610f\u4e4b\u8868\u696d\uff0c\u6212\u9ad4\u4e0d\u640d\uff08\u6b63\u7406\u56db\uff09\uff1b'
        u'\u7136\u50e7\u5718\u70ba\u9632\u5f8c\u60a3\uff0c\u5225\u5236\u4f5b\u5df1\u6bd4\u4e18\u5e94\u5148\u89c0\u9580\u5df7\u7a7a\u8655\u2014\u2014\u4e0d\u7f6a\u5176\u8eab\u800c\u56b4\u5176\u4e8b\u3002'),
    92: (u'\u5c11\u5be9\u7fa9\u800c\u5927\u50e7\u4e0d\u80fd\u7b54\uff0c\u662f\u72af\u554f\u8005\uff0c\u9084\u662f\u72af\u4e0d\u5b78\u8005\uff1f\u6cd5\u4e4b\u7f9e\u8207\u5229\u4ed6\u4e4b\u5fc3\u5982\u4f55\u5169\u5206\uff1f',
        u'**\u3010\u6ce2\u9038\u63d0\uff08\u554f\u6642\u4e4b\u5a01\u5100\uff09\u3011**<br>'
        u'\u7d50\u7f6a\u5728\u4e0d\u4f9d\u6b21\u5e8f\u3001\u4e0d\u6545\u614b\u800c\u554f\uff0c\u4e0d\u5728\u554f\u6cd5\u672c\u8eab\uff1b\u5927\u50e7\u4e0d\u80fd\u7b54\uff0c\u5225\u81ea\u52c9\u5b78\u3002'
        u'\u4e00\u554f\u4e00\u7b54\u5169\u5404\u5176\u8cec\uff0c\u4e0d\u8a31\u4ee5\u7f9e\u6557\u596a\u5176\u554f\u6cd5\u4e4b\u6b0a\u3002'),
    94: (u'\u4f4f\u5783\u9593\u800c\u81ea\u8a00\u751a\u6a02\uff0c\u662f\u589e\u4e0a\u6162\u8207\u5be6\u8b49\uff1f\u9053\u5834\u5f97\u5426\u4ee5\u300e\u6a02\u4e0d\u5982\u6211\u300f\u79d1\u4eba\uff1f',
        u'**\u3010\u7121\u72af\uff08\u5404\u96a8\u5176\u7de3\uff09\u3011**<br>'
        u'\u8209\u63d0\u6a02\u5728\u5783\u9593\uff0c\u4f5b\u4e0d\u4ee5\u5176\u6240\u6a02\u70ba\u7570\uff1b\u884c\u8005\u4e4b\u6240\u5b89\uff0c\u975e\u5e38\u60c5\u53ef\u91cf\u3002'
        u'\u6545\u5f8b\u4e0d\u7acb\u300e\u5fc5\u9808\u540c\u82e6\u300f\u4e4b\u689d\u2014\u2014\u6b64\u70ba\u6212\u7981\u53d6\u898b\u4e4b\u53cd\u9762\u6559\u6750\u3002'),
    95: (u'\u4f5b\u81ea\u6d17\u75c5\uff0c\u662f\u6148\u60b2\u9084\u662f\u8d85\u5206\uff1f\u770b\u75c5\u4e4b\u7fa9\u52d9\u53ef\u63a8\u7d66\u8ab0\uff1f\u4e0d\u63a8\u662f\u5426\u5373\u72af\uff1f',
        u'**\u3010\u4f5c\u6301\u4e4b\u6975\uff08\u6709\u8cec\u7121\u5211\uff09\u3011**<br>'
        u'\u300e\u61c9\u770b\u75c5\u6bd4\u4e18\uff0c\u4e0d\u5e94\u4e0d\u770b\u300f\u662f\u6559\u4ee4\u4e4b\u91cd\u8005\uff0c\u7136\u9055\u4e4b\u4e0d\u5165\u50e7\u6b98\u2014\u2014\u8cec\u5728\u7fa9\u52d9\uff0c\u4e0d\u5728\u5211\u540d\u3002'
        u'\u4ee5\u5982\u4f86\u89aa\u6d17\u7acb\u6a19\u6e96\uff0c\u6545\u5f8c\u4e16\u4e0d\u5f97\u4ee5\u61f0\u61f2\u70ba\u89aa\u9ad8\u3002'),
    100: (u'\u8209\u4f5b\u6d85\u76e4\u800c\u8638\u6068\uff0c\u662f\u60c5\u6df1\u9084\u662f\u72af\u5883\uff1f\u672a\u96e2\u6b32\u8005\u4e4b\u54c0\uff0c\u7576\u4f55\u6cd5\u5171\u4e4b\uff1f',
        u'**\u3010\u60c5\u6975\u514d\u6aa2\uff0c\u7acb\u8aaa\u6cd5\u4e4b\u85e5\u3011**<br>'
        u'\u672a\u96e2\u6b32\u8005\u805e\u6d85\u76e4\u800c\u6d95\u6068\uff0c\u5f8b\u4e0d\u7d50\u7f6a\uff1b\u5927\u8449\u5373\u662d\u672a\u96e2\u6b32\u8005\u51fa\uff0c\u7559\u5df2\u96e2\u6b32\u8005\u805e\u6cd5\u3002'
        u'\u8655\u5206\u4e0d\u5728\u8cec\u5176\u60b2\uff0c\u800c\u5728\u7d66\u5176\u6cd5\u2014\u2014\u6b64\u5373\u6b63\u7406\u4e03\u7559\u751f\u8def\u4e4b\u5178\u578b\u3002'),
    58: (u'\u5e74\u4e0d\u8db3\u800c\u53d7\u5177\uff0c\u7f6a\u5728\u53d7\u8005\u3001\u6388\u8005\uff0c\u6296\u5404\uff1f\u53d7\u8005\u591a\u5e74\u5f8c\u767c\u89ba\uff0c\u4e0b\u6e38\u662f\u5426\u540c\u8461\uff1f',
        u'**\u3010\u6ce2\u9038\u63d0\uff08\u6388\u8005\u7368\u4efb\uff09\u3011**<br>'
        u'\u7d50\u8cec\u5728\u548c\u5c1a\u300e\u77e5\u5176\u4e0d\u8db3\u800c\u8207\u53d7\u300f\uff1b\u53d7\u8005\u81ea\u59cb\u4e0d\u5f97\u5927\u6212\uff0c\u8eab\u5206\u50c5\u6b78\u6c99\u5f4c\uff0c\u5e74\u6eff\u807d\u91cd\u53d7\u3002'
        u'\u5176\u53c3\u8207\u4e4b\u5e38\u614b\u5278\u78e8\u8207\u53d7\u6212\u8005\uff0c\u4f9d\u73fe\u524d\u6e05\u6de8\u64ec\u5236\u8207\u5584\u610f\u4fe1\u8cf4\u4fdd\u8b77\uff0c\u4e0d\u6eaf\u53ca\u63a8\u7ffb\u3002'),
}

n_ok = 0
for i, l in enumerate(LINES):
    if TPL not in l:
        continue
    m = re.search(u'\u3014\u6848\u4f8b ?0*(\\d+)', l)
    if not m or int(m.group(1)) not in FIX:
        print(u'  \u672a\u5217\u884c\uff1aL%d \u6848%s' % (i + 1, m.group(1) if m else u'?'))
        continue
    n = int(m.group(1))
    cells = l.split(u'|')
    assert len(cells) == 7, (i + 1, len(cells))
    cells[3] = u' ' + FIX[n][0] + u' '
    cells[4] = u' ' + FIX[n][1] + u' '
    LINES[i] = u'|'.join(cells)
    n_ok += 1
print(u'\u6539\u52d9\u9ede\u8207\u8655\u65b7\u6b04\uff1a%d \u884c' % n_ok)
left = sum(1 for l in LINES if TPL in l)
print(u'\u5957\u8a9e\u908a\u5b58 %d \u884c' % left)
out = u'\n'.join(LINES)
print(u'\u6539\u5f8c %d \u884c\uff0dsha %s' % (len(LINES), hashlib.sha256(out.encode(u'utf-8')).hexdigest()[:12]))
if not APPLY:
    print(u'\uff08\u4e7e\u8dd1\u30fb\u672a\u843d\u76e4\uff09')
    sys.exit(0)
if not os.path.exists(BAK):
    io.open(BAK, 'w', encoding=u'utf-8').write(TXT)
io.open(BOOK, 'w', encoding=u'utf-8').write(out)
print(u'\u843d\u76e4\u8a3c')
